"""Keep regions: parts of a generated file that belong to the service repository.

A generated file (one with the "Generated by sdk-kit" header) can mark regions whose body the
service owns::

    <!-- @sdk-kit:keep service-settings -->
    ...service-owned lines...
    <!-- @sdk-kit:endkeep -->

The marker lines use the same comment styles as ``@sdk-kit:if`` (``//``, ``#``, ``<!--``, ``/*``,
``--``); text after the region name is a free description. ``sdk-kit new`` writes the template's
default body. ``sdk-kit sync`` re-renders the file but keeps the body the repository has for each
region of the same name, and the SHA-256 recorded in ``.sdk-kit.json`` is taken with every region
body removed, so editing a region never counts as a local modification. Regions do not nest and
names are unique within a file.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

KEEP_RE = re.compile(
    r"^\s*(?://|#|<!--|/\*|--)\s*@sdk-kit:"
    r"(?:keep\s+(?P<name>[A-Za-z0-9][A-Za-z0-9_.-]*)(?:\s+.*?)?|(?P<end>endkeep))"
    r"\s*(?:-->|\*/)?\s*$"
)
_ANY_KEEP_RE = re.compile(r"@sdk-kit:(?:keep|endkeep)\b")


class KeepError(ValueError):
    """Malformed keep markers (unclosed, nested, duplicate name, stray end marker)."""


@dataclass(frozen=True)
class Region:
    """One keep region: marker line indexes (0-based) into ``text.splitlines(keepends=True)``."""

    name: str
    start: int
    end: int


def is_keep_marker(line: str) -> bool:
    """True when ``line`` is a ``@sdk-kit:keep`` or ``@sdk-kit:endkeep`` marker line."""
    return KEEP_RE.match(line.rstrip("\r\n")) is not None


def parse(text: str, where: str = "<text>") -> list[Region]:
    """The keep regions of ``text`` in file order; raises :class:`KeepError` when malformed."""
    if "@sdk-kit:" not in text:
        return []
    regions: list[Region] = []
    seen: dict[str, int] = {}
    open_name: str | None = None
    open_at = 0
    for index, line in enumerate(text.splitlines(keepends=True)):
        match = KEEP_RE.match(line.rstrip("\r\n"))
        if match is None:
            if _ANY_KEEP_RE.search(line) and line.lstrip().startswith(("//", "#", "<!--", "/*", "--")):
                raise KeepError(f"{where}:{index + 1}: malformed keep marker: {line.strip()!r}")
            continue
        name = match.group("name")
        if name is not None:
            if open_name is not None:
                raise KeepError(
                    f"{where}:{index + 1}: @sdk-kit:keep {name} inside the region {open_name!r} "
                    f"opened on line {open_at + 1} (keep regions do not nest)"
                )
            if name in seen:
                raise KeepError(
                    f"{where}:{index + 1}: duplicate keep region {name!r} (first on line {seen[name]})"
                )
            seen[name] = index + 1
            open_name, open_at = name, index
            continue
        if open_name is None:
            raise KeepError(f"{where}:{index + 1}: @sdk-kit:endkeep without @sdk-kit:keep")
        regions.append(Region(open_name, open_at, index))
        open_name = None
    if open_name is not None:
        raise KeepError(f"{where}:{open_at + 1}: keep region {open_name!r} is never closed")
    return regions


def bodies(text: str, where: str = "<text>") -> dict[str, str]:
    """``{name: body}`` of every region (the lines between the markers, line endings kept)."""
    lines = text.splitlines(keepends=True)
    return {r.name: "".join(lines[r.start + 1 : r.end]) for r in parse(text, where)}


def strip(text: str) -> str:
    """``text`` with every region body removed (markers kept); unchanged when malformed."""
    try:
        regions = parse(text)
    except KeepError:
        return text
    if not regions:
        return text
    lines = text.splitlines(keepends=True)
    out: list[str] = []
    cursor = 0
    for region in regions:
        out += lines[cursor : region.start + 1]
        cursor = region.end
    out += lines[cursor:]
    return "".join(out)


def strip_bytes(data: bytes) -> bytes:
    """:func:`strip` for file content; binary content is returned unchanged."""
    if b"@sdk-kit:" not in data or b"\0" in data[:8192]:
        return data
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return data
    return strip(text).encode("utf-8")


@dataclass(frozen=True)
class Merge:
    """Result of :func:`merge`."""

    text: str
    kept: tuple[str, ...]  # regions whose body came from the existing file
    dropped: tuple[str, ...]  # non-empty regions of the existing file the template no longer has


def merge(rendered: str, existing: str, where: str = "<text>") -> Merge:
    """Put the region bodies of ``existing`` into ``rendered``.

    Regions missing from ``existing`` keep the template's default body. A malformed ``existing``
    contributes nothing (the caller then sees it as locally modified).
    """
    regions = parse(rendered, where)
    try:
        current = bodies(existing, where)
    except KeepError:
        current = {}
    names = {r.name for r in regions}
    dropped = tuple(n for n, body in current.items() if n not in names and body.strip())
    if not regions:
        return Merge(rendered, (), dropped)
    lines = rendered.splitlines(keepends=True)
    out: list[str] = []
    kept: list[str] = []
    cursor = 0
    for region in regions:
        out += lines[cursor : region.start + 1]
        if region.name in current:
            out.append(current[region.name])  # whole lines: the end marker starts a new line
            kept.append(region.name)
        else:
            out += lines[region.start + 1 : region.end]
        cursor = region.end
    out += lines[cursor:]
    return Merge("".join(out), tuple(kept), dropped)
